import math, sys
sys.path.insert(0, ".")
import analysis as A

# 1000 Hz carrier gated at 120 BPM with smooth (raised-cosine) envelope:
# spectral energy stays near 1 kHz, nothing rhythmic lands in the 40-150 Hz band.
def gated(bpm=120.0, seconds=8.0, rate=4000, f=1000.0, gate_ms=250.0, edge_ms=25.0):
    n=int(seconds*rate); out=[0.0]*n
    period=60.0/bpm; g=int(gate_ms*rate/1000); e=int(edge_ms*rate/1000)
    t=0.3
    while t < seconds-0.01:
        i0=int(t*rate)
        for j in range(min(g, n-i0)):
            env = 1.0
            if j < e: env = 0.5*(1-math.cos(math.pi*j/e))
            elif j > g-e: env = 0.5*(1-math.cos(math.pi*(g-j)/e))
            out[i0+j]=0.6*math.sin(2*math.pi*f*j/rate)*env
        t+=period
    return out

def kick_bpm(sig, rate):
    s = A._decimate(sig, rate) if rate > A.ANALYSIS_RATE else sig
    co = A._biquad_bandpass(rate if rate<=A.ANALYSIS_RATE else 4000, A.BANDPASS_LO, A.BANDPASS_HI)
    k = A._apply_biquad(s, co)
    return A._detect_tempo(A._odf(k), 4000/A.HOP)

for rate in (4000, 44100):
    sig = gated(rate=rate)
    print(rate, "kick=", kick_bpm(sig, rate), "broad=", A._detect_tempo(A._odf(A._decimate(sig, rate) if rate>4000 else sig), 4000/A.HOP), "analyze=", A.analyze_samples(sig, rate))
